describe('Modal Focus Trap', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000');
    cy.get('[data-testid="open-modal-btn"]').click();
    cy.get('[data-testid="modal"]').should('be.visible');
  });

  it('should trap focus within modal when tabbing through focusable elements', () => {
    // Get all focusable elements in the modal
    cy.get('[data-testid="modal"]').within(() => {
      cy.get('button, [href], input, select, textarea, [tabindex]').first().focus();
    });

    // Tab through elements and verify focus stays within modal
    cy.focused().should('have.attr', 'data-testid').and('include', 'modal');

    cy.get('[data-testid="modal"]').within(() => {
      cy.get('button').first().focus();
      cy.realPress('Tab');
      cy.focused().should('have.attr', 'data-testid').and('not.equal', 'outside-element');
    });

    // Tab to last focusable element
    cy.get('[data-testid="modal"]').within(() => {
      cy.get('button, [href], input, select, textarea, [tabindex]').last().focus();
      cy.realPress('Tab');
      // Focus should wrap back to first focusable element in modal
      cy.focused().should('have.attr', 'data-testid').and('include', 'modal');
    });
  });

  it('should trap focus when shift+tab is pressed on first focusable element', () => {
    cy.get('[data-testid="modal"]').within(() => {
      cy.get('button, [href], input, select, textarea, [tabindex]').first().focus();
    });

    // Shift+Tab from first element should wrap to last focusable element
    cy.realPress(['Shift', 'Tab']);
    cy.focused().should('have.attr', 'data-testid').and('include', 'modal');

    // Verify focus is on a modal element, not outside
    cy.get('[data-testid="modal"]').should('contain', cy.focused());
  });

  it('should prevent focus from moving to elements outside the modal', () => {
    cy.get('[data-testid="outside-element"]').should('exist');

    cy.get('[data-testid="modal"]').within(() => {
      cy.get('button').first().focus();
    });

    // Try to tab multiple times and verify we never reach outside element
    for (let i = 0; i < 10; i++) {
      cy.realPress('Tab');
      cy.focused().should('not.have.attr', 'data-testid', 'outside-element');
    }
  });

  it('should restore focus to trigger element when modal is closed', () => {
    cy.get('[data-testid="open-modal-btn"]').focus();
    cy.get('[data-testid="modal"]').should('be.visible');

    cy.get('[data-testid="close-modal-btn"]').click();
    cy.get('[data-testid="modal"]').should('not.be.visible');

    // Focus should return to the button that opened the modal
    cy.focused().should('have.attr', 'data-testid', 'open-modal-btn');
  });

  it('should handle escape key and maintain focus trap until closed', () => {
    cy.get('[data-testid="modal"]').within(() => {
      cy.get('input').first().focus();
    });

    cy.realPress('Escape');
    cy.get('[data-testid="modal"]').should('not.be.visible');
    cy.focused().should('have.attr', 'data-testid', 'open-modal-btn');
  });
});
